import json, os, socket, subprocess, sys, time, base64, urllib.request, shutil, pathlib
import websocket

TARGET = sys.argv[1]
OUTDIR = pathlib.Path(sys.argv[2]); OUTDIR.mkdir(parents=True, exist_ok=True)
CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
udd = OUTDIR / "chrome-profile"
if udd.exists(): shutil.rmtree(udd)
s = socket.socket(); s.bind(("127.0.0.1", 0)); PORT = s.getsockname()[1]; s.close()

proc = subprocess.Popen([CHROME, "--headless=new", f"--remote-debugging-port={PORT}",
    f"--user-data-dir={udd}", "--no-first-run", "--no-default-browser-check",
    "--disable-background-networking", "--disable-component-update", "--disable-sync",
    "--disable-default-apps", "--metrics-recording-only", "--no-sandbox",
    "--allow-file-access-from-files", "--window-size=1280,1400"],
    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

ver = None
for _ in range(120):
    try:
        ver = json.loads(urllib.request.urlopen(f"http://127.0.0.1:{PORT}/json/version", timeout=1).read())
        break
    except Exception: time.sleep(0.25)
assert ver, "chrome did not start"
browser_ws = ver["webSocketDebuggerUrl"]
print("BROWSER:", ver.get("Browser"), "| UA:", ver.get("User-Agent"))

ws = websocket.create_connection(browser_ws, timeout=30, max_size=64*1024*1024)
_id = [0]
def send(method, params=None, sess=None):
    _id[0]+=1; msg={"id":_id[0],"method":method,"params":params or {}}
    if sess: msg["sessionId"]=sess
    ws.send(json.dumps(msg)); return _id[0]

events=[]
def wait(mid, timeout=30):
    end=time.time()+timeout
    while time.time()<end:
        m=json.loads(ws.recv())
        if m.get("id")==mid: return m
        events.append(m)
    raise TimeoutError(f"no response for {mid}")

t=wait(send("Target.createTarget",{"url":"about:blank"}))["result"]["targetId"]
sess=wait(send("Target.attachToTarget",{"targetId":t,"flatten":True}))["result"]["sessionId"]
for d in ("Page","Network","Runtime","Log"): wait(send(f"{d}.enable",{},sess))
wait(send("Page.navigate",{"url":TARGET},sess))
time.sleep(4)
# drain
ws.settimeout(1.0)
try:
    while True: events.append(json.loads(ws.recv()))
except Exception: pass
ws.settimeout(30)

reqs=[e["params"]["request"]["url"] for e in events if e.get("method")=="Network.requestWillBeSent"]
console=[e["params"] for e in events if e.get("method") in ("Runtime.consoleAPICalled","Log.entryAdded")]
excs=[e["params"] for e in events if e.get("method")=="Runtime.exceptionThrown"]
loadfail=[e["params"] for e in events if e.get("method")=="Network.loadingFailed"]

EXPR = r"""
(() => {
  const svg = document.querySelector('svg');
  const r = svg ? svg.getBoundingClientRect() : null;
  const nodes = [...document.querySelectorAll('.node')];
  const vis = nodes.filter(n => n.getBoundingClientRect().width > 0 && !n.classList.contains('hidden'));
  const label = el => [...el.querySelectorAll('text')].map(t => t.textContent).join(' | ');
  const feat = nodes.find(n => label(n).includes('feature'));
  const payload = JSON.parse(document.querySelector('#graph-data').textContent);
  const kids = payload.filter(p => p.parent_feature === 'LT-FEATURE-001');
  const done = kids.filter(p => p.status === 'done').length;
  // interaction test on inline JS
  const q = document.querySelector('#q');
  q.value = 'SYS-LTF001-P05';
  q.dispatchEvent(new Event('input'));
  const afterFilter = nodes.filter(n => !n.classList.contains('hidden')).length;
  q.value = ''; q.dispatchEvent(new Event('input'));
  const afterClear = nodes.filter(n => !n.classList.contains('hidden')).length;
  return {
    svg_present: !!svg,
    svg_box: r ? {w: Math.round(r.width), h: Math.round(r.height)} : null,
    svg_computed_display: svg ? getComputedStyle(svg).display : null,
    node_groups: nodes.length,
    visible_nodes: vis.length,
    edge_paths: document.querySelectorAll('.edges path').length,
    feature_label: feat ? label(feat) : null,
    feature_progress_text: feat ? (label(feat).match(/(\d+)\/(\d+)/) || []).slice(1) : null,
    recomputed_from_parent_feature: {done: done, total: kids.length},
    payload_nodes: payload.length,
    payload_edges: payload.reduce((a,p)=>a+p.depends_on.length,0),
    filter_visible_for_P05: afterFilter,
    visible_after_clear: afterClear,
    stylesheets: document.styleSheets.length,
    scripts_with_src: document.querySelectorAll('script[src]').length,
    link_elements: document.querySelectorAll('link').length,
    title: document.title
  };
})()
"""
res = wait(send("Runtime.evaluate", {"expression": EXPR, "returnByValue": True}, sess))
val = res["result"]["result"].get("value")
shot = wait(send("Page.captureScreenshot", {"format":"png","captureBeyondViewport":True}, sess), 60)
(OUTDIR/"live-trial.png").write_bytes(base64.b64decode(shot["result"]["data"]))

report = {"browser": ver.get("Browser"), "network_requests": reqs,
          "external_requests": [u for u in reqs if not u.startswith("file://")],
          "loading_failed": loadfail, "console": console, "exceptions": excs, "dom": val,
          "screenshot": str(OUTDIR/"live-trial.png")}
print(json.dumps(report, ensure_ascii=False, indent=2))
ws.close(); proc.terminate()
PY
